#!/usr/bin/env bash
# Enemy clothing and gear skinned to the MetaHuman skeleton (assets/models/metahuman/gear_mh.glb),
# generated by headless Blender from the local MetaHuman enemy (scripts/make-metahuman.sh). The
# geometry is ours, but its skin weights come from the MetaHuman body, so the output stays local
# like the MetaHuman itself (gitignored). Without it the enemy wears the primitive kit.
#
#   scripts/make-gear-mh.sh        (BLENDER=<path> to override the Blender binary)
set -euo pipefail
cd "$(dirname "$0")/.."
BLENDER="${BLENDER:-/Applications/Blender.app/Contents/MacOS/Blender}"
SRC=assets/models/metahuman/enemy_mh.glb
OUT=assets/models/metahuman/gear_mh.glb
[ -f "$SRC" ] || { echo "no $SRC: run scripts/make-metahuman.sh first" >&2; exit 1; }
"$BLENDER" -b --factory-startup --python scripts/blender/make_gear_mh.py -- "$SRC" "$OUT" 2>&1 \
  | grep -E '^(gear|carrier|sole|  [a-z])|Error|Traceback' || true
# Blender re-rolls bones on export: take the inverse binds from the enemy's own skeleton.
python3 -I scripts/gear_rebind.py "$SRC" "$OUT"
echo "wrote $OUT"
